import { gsap } from 'gsap';
import { Texture } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { MeshLambertNodeMaterial } from 'three/webgpu';
import { MeshPhongNodeMaterial } from 'three/webgpu';
import { Mesh } from 'three/webgpu';
import { Object3D } from 'three/webgpu';
import { Group } from 'three/webgpu';
/**
 * @typedef {import('./types').NodeConfig} NodeConfig
 * @typedef {import('./types').NodeContext} NodeContext
 */

/**
 * Creates the ornamental divider node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;

  /** @type {THREE.Group} */
  const root = new Group();

  // store handles for cleanup
  const timelines = [];

  // Load GLB mesh
  const glbPromise = ctx.glbLoader.loadGLB(config.meshUrl);
  glbPromise.then((gltf) => {
    // gltf.scene is an Object3D hierarchy
    root.add(gltf.scene);
    // Optional: keep reference for later disposal
    root.userData._gltf = gltf;
  });

  /** Hover enter effect */
  const onHoverEnter = () => {
    const startY = root.position.y;
    const tl = gsap.timeline({ onComplete: () => { const idx = timelines.indexOf(tl); if (idx > -1) timelines.splice(idx, 1); } });
    tl.to(root.position, {
      y: startY + 0.15,
      duration: 0.15,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };

  /** Hover leave effect */
  const onHoverLeave = () => {
    const tl = gsap.timeline({ onComplete: () => { const idx = timelines.indexOf(tl); if (idx > -1) timelines.splice(idx, 1); } });
    tl.to(root.position, {
      y: root.position.y - 0.15,
      duration: 0.15,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };

  /** Click effect */
  const onClick = () => {
    ctx.emit('hub-home.select');

    const tl = gsap.timeline({ onComplete: () => { const idx = timelines.indexOf(tl); if (idx > -1) timelines.splice(idx, 1); } });
    tl.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    }).to(
      root.scale,
      {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out(1.7)',
      },
      '+=0.05'
    );
    timelines.push(tl);
  };

  // Attach handlers map
  root.userData.handlers = {
    hoverEnter: onHoverEnter,
    hoverLeave: onHoverLeave,
    click: onClick,
  };

  // Cleanup routine
  const cleanup = () => {
    // Kill all GSAP timelines
    timelines.forEach((t) => t.kill());
    timelines.length = 0;

    // Dispose GLTF resources if loaded
    const gltf = root.userData._gltf;
    if (gltf && gltf.scene) {
      gltf.scene.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          const mat = child.material;
          if (Array.isArray(mat)) {
            mat.forEach(disposeMaterial);
          } else if (mat) {
            disposeMaterial(mat);
          }
        }
      });
    }

    // Remove all children from the group
    while (root.children.length) {
      root.remove(root.children[0]);
    }
  };

  /** Dispose a material and its textures */
  function disposeMaterial(material) {
    if (!material) return;
    if (material.map) material.map.dispose();
    if (material.lightMap) material.lightMap.dispose();
    if (material.bumpMap) material.bumpMap.dispose();
    if (material.normalMap) material.normalMap.dispose();
    if (material.displacementMap) material.displacementMap.dispose();
    if (material.roughnessMap) material.roughnessMap.dispose();
    if (material.metalnessMap) material.metalnessMap.dispose();
    if (material.alphaMap) material.alphaMap.dispose();
    if (material.envMap) material.envMap.dispose();
    material.dispose();
  }

  root.userData.cleanup = cleanup;

  // Expose binding placeholder (no runtime logic required)
  root.userData.bindings = [
    {
      source: 'trpc.visits.book.slot',
      target: 'confirmPanel',
    },
  ];

  return root;
}
